import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;
    static long[] factorialCache;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        String line = reader.readLine();
        int t = 1;
        while (t-- > 0) {
            String[] parts = line.trim().split(" ");
            int n = Integer.parseInt(parts[0]);
            long kVal = Long.parseLong(parts[1]);
            factorialCache = new long[n + 1];
            factorialCache[0] = 1L;
            for (int i = 1; i <= n; i++) {
                factorialCache[i] = (factorialCache[i - 1] * i) % MOD;
            }
            if (kVal == 0) {
                out.println(factorialCache[n]);
            } else if (kVal >= n) {
                out.println(0);
            } else {
                int k = (int) kVal;
                long totalSum = 0L;
                long signFlag = 1L;
                int l = n - k;
                for (int i = 0; i <= l; i++) {
                    long term = (quickExponentiation(l - i, n) * combination(l, l - i)) % MOD;
                    totalSum = (totalSum + signFlag * term + MOD) % MOD;
                    signFlag *= -1L;
                }
                long answer = (2L * combination(n, k) * totalSum) % MOD;
                out.println(answer);
            }
        }
        out.close();
    }

    static long combination(int n, int r) {
        if (r == 0 || r == n) return 1L;
        if (r > n || r < 0) return 0L;
        long numerator = factorialCache[n];
        long denominator = (factorialCache[r] * factorialCache[n - r]) % MOD;
        return (numerator * quickPow(denominator, MOD - 2)) % MOD;
    }

    static long quickExponentiation(long base, long exp) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }
}
